<?php
function achievement_badge(?array $title): void { if($title): ?><span class="rank-badge <?=escape($title['class'])?>" title="Completed achievement tier"><span aria-hidden="true">◆</span> <?=escape($title['title'])?></span><?php endif; }
function show_achievement_levels(array $progress): void { foreach($progress['levels'] as $level): ?>
<details class="achievement-tier <?=escape($level['class'])?>"><summary class="tier-summary"><span class="tier-summary-top"><span class="tier-identity"><span class="tier-name"><?=escape($level['name'])?></span><span class="tier-reward">Title: <?=escape($level['title'])?></span></span><span class="tier-tally"><?=(int)$level['earned']?> / <?=(int)$level['total']?> completed</span><span class="tier-chevron" aria-hidden="true"></span></span><span class="tier-progress" role="progressbar" aria-label="<?=escape($level['name'])?> progress" aria-valuemin="0" aria-valuenow="<?=(int)$level['earned']?>" aria-valuemax="<?=max(1,$level['total'])?>"><span style="width:<?=$level['total']?100*$level['earned']/$level['total']:0?>%"></span></span></summary><div class="achievement-list"><?php foreach($level['entries'] as $entry): ?><article class="achievement-entry"><div><strong><?=escape($entry['title'])?></strong><p><?=escape($entry['description'])?></p></div><span class="badge <?=$entry['earned_at']?'bg-success':'bg-secondary'?>"><?=$entry['earned_at']?'Earned':'Locked'?></span></article><?php endforeach; ?></div></details>
<?php endforeach; }
